import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.B2Q7dRKp.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":1776508966000}'),d={name:"guide/troubleshooting.md"};function r(s,e,l,n,h,c){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="login" tabindex="-1">Login <a class="header-anchor" href="#login" aria-label="Permalink to &quot;Login&quot;">​</a></h2><h3 id="login-failed-—-akamai-halt" tabindex="-1"><code>Login failed — Akamai halt</code> <a class="header-anchor" href="#login-failed-—-akamai-halt" aria-label="Permalink to &quot;`Login failed — Akamai halt`&quot;">​</a></h3><p>Proxy IP reputation is flagged. Switch to residential, or wait 30–60 min.</p><h3 id="login-failed-—-403-elevated-risk-score" tabindex="-1"><code>Login failed — 403 elevated-risk-score</code> <a class="header-anchor" href="#login-failed-—-403-elevated-risk-score" aria-label="Permalink to &quot;`Login failed — 403 elevated-risk-score`&quot;">​</a></h3><p>Same cause. Residential proxies with clean IPs fix it.</p><h3 id="login-failed-—-401-xsrf-validation-failed" tabindex="-1"><code>Login failed — 401 Xsrf validation failed</code> <a class="header-anchor" href="#login-failed-—-401-xsrf-validation-failed" aria-label="Permalink to &quot;`Login failed — 401 Xsrf validation failed`&quot;">​</a></h3><p>CSRF cookie wasn&#39;t set during warm-up. Usually means the proxy blocked the <code>/login</code> GET. Try a different proxy.</p><h3 id="saved-cookies-expired-on-every-run" tabindex="-1"><code>Saved cookies expired</code> on every run <a class="header-anchor" href="#saved-cookies-expired-on-every-run" aria-label="Permalink to &quot;`Saved cookies expired` on every run&quot;">​</a></h3><p><code>sessions/</code> folder isn&#39;t writable. Move the exe to a user-writable location.</p><h2 id="checkout" tabindex="-1">Checkout <a class="header-anchor" href="#checkout" aria-label="Permalink to &quot;Checkout&quot;">​</a></h2><h3 id="checkout-failed-—-no-saved-address" tabindex="-1"><code>Checkout failed — no saved address</code> <a class="header-anchor" href="#checkout-failed-—-no-saved-address" aria-label="Permalink to &quot;`Checkout failed — no saved address`&quot;">​</a></h3><p>Account has no default delivery address. Register with address columns, or add it once via the site UI and delete the session cache to pick it up.</p><h3 id="checkout-failed-—-order-token-expired" tabindex="-1"><code>Checkout failed — order-token-expired</code> <a class="header-anchor" href="#checkout-failed-—-order-token-expired" aria-label="Permalink to &quot;`Checkout failed — order-token-expired`&quot;">​</a></h3><p>Transient — retry. Fixed permanently in v1.2.0+.</p><h3 id="payment-session-token-not-found" tabindex="-1"><code>Payment session/token not found</code> <a class="header-anchor" href="#payment-session-token-not-found" aria-label="Permalink to &quot;`Payment session/token not found`&quot;">​</a></h3><p>Cart was empty at checkout (ATC failed silently). Check the preceding ATC step.</p><h3 id="order-problem-code" tabindex="-1"><code>Order problem: &lt;code&gt;</code> <a class="header-anchor" href="#order-problem-code" aria-label="Permalink to &quot;`Order problem: &lt;code&gt;`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>place-order.order-token-expired</code></td><td>Stale session — retry</td></tr><tr><td><code>place-order.inventory-reserved-by-others</code></td><td>OOS between ATC and place-order</td></tr><tr><td><code>place-order.payment-method-invalid</code></td><td>PayPal not available for this item/country</td></tr><tr><td><code>place-order.address-invalid</code></td><td>Saved address is malformed</td></tr></tbody></table><h2 id="launcher" tabindex="-1">Launcher <a class="header-anchor" href="#launcher" aria-label="Permalink to &quot;Launcher&quot;">​</a></h2><h3 id="exits-immediately-with-no-output" tabindex="-1">Exits immediately with no output <a class="header-anchor" href="#exits-immediately-with-no-output" aria-label="Permalink to &quot;Exits immediately with no output&quot;">​</a></h3><p>CSV parse error swallowed by the exe. Run from PowerShell so the error stays visible:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd C:\\Users\\</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">you</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\Desktop\\AxgstAIO</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">axgstaio.exe</span></span></code></pre></div><h3 id="update-failed-http-403" tabindex="-1"><code>Update failed: HTTP 403</code> <a class="header-anchor" href="#update-failed-http-403" aria-label="Permalink to &quot;`Update failed: HTTP 403`&quot;">​</a></h3><p>GitHub API rate-limit. Wait an hour or download manually.</p>',25)])])}const k=a(d,[["render",r]]);export{u as __pageData,k as default};
